  tpl_h: "Modèles",
  tpl_lead: "<b>Emkay: New skill</b> vous laisse choisir. Chaque modèle est une vraie skill qui fonctionne, dans son propre dépôt – vous pouvez aussi partir de lui sur GitHub.",
  tpl_open: "Sur GitHub",
  tpl_kind_skill: "Skill",
