  b_can_listen_h: "Escuchar y empezar",
  b_can_listen_p: "Cuando alguien dice…, lo que se dijo para {ciudad}, cada día a las siete, cada diez minutos, cuando Emkay arranca.",
  b_can_speak_h: "Hablar y mostrar",
  b_can_speak_p: "Di, di una de (una respuesta nueva cada vez), pregunta, sí o no, elige de una lista, y texto e imágenes en la pantalla.",
  b_can_time_h: "Tiempo",
