  gal_see_all: "Vedi tutte le {n} skill →",
  gal_ex_h: "Esempi da cui partire",
  gal_ex_lead: "Fatti da Emkay per imparare – ognuno una skill o un plugin completo che funziona. Provane uno nel tuo Emkay, leggi il codice, o parti da lì per la tua con <b>Emkay: Nuova skill</b>.",
  gal_ex_tag: "esempio",
